import type { PipelineContext } from "aipod-node";

export class PriceOrder {
  constructor(_dependencies: Record<never, never> = {}) {}

  execute(context: PipelineContext): { totalCents: number } {
    const ctx = context.typed(
      { amountCents: { type: "integer" } },
      { totalCents: { type: "integer" } }
    );

    const amountCents = ctx.get("amountCents");
    const totalCents = amountCents < 10000 ? amountCents : amountCents - 1000;

    ctx.set("totalCents", totalCents);

    return ctx.output({ totalCents });
  }
}
